//! Country-specific state/province name to ISO 3166-2 subdivision code lookup.
//!
//! The data is generated from Euler `StateISO` and kept in UCS so every
//! connector receives the same normalized state code independent of the
//! upstream caller. It was ported from euler-db commit
//! `e2bf5cfa5be52d5c42cf0a7a4558827ca895a130`.

