static STATE_CODE_MAP: LazyLock<HashMap<(&'static str, &'static str), &'static str>> =
    LazyLock::new(|| STATE_CODE_ENTRIES.iter().copied().collect());

fn fold_character(character: char, output: &mut String) {
    match character {
        '\'' | '.' | '\u{ad}' | '\u{2bb}' | '\u{2bc}' | '\u{200b}' | '\u{200c}' | '\u{200d}'
        | '\u{2018}' | '\u{2019}' | '\u{2020}' | '\u{feff}' | '\u{ff07}' | '\u{ff0c}'
        | '\u{ff0d}' | '\u{ff0e}' | '\u{ff0f}' | '\u{ff3f}' => output.push_str(""),
        ',' | '-' | '/' | '_' | '\u{2010}' | '\u{2011}' | '\u{2012}' | '\u{2013}' | '\u{2014}' => {
            output.push_str(" ")
        }
        '\u{ff01}' => output.push_str("!"),
        '\u{ff02}' => output.push_str("\""),
        '\u{ff03}' => output.push_str("#"),
        '\u{ff04}' => output.push_str("$"),
        '\u{ff05}' => output.push_str("%"),
        '\u{ff06}' => output.push_str("&"),
        '\u{ff08}' => output.push_str("("),
        '\u{ff09}' => output.push_str(")"),
        '\u{ff0a}' => output.push_str("*"),
        '\u{ff0b}' => output.push_str("+"),
        '\u{ff10}' => output.push_str("0"),
        '\u{ff11}' => output.push_str("1"),
        '\u{ff12}' => output.push_str("2"),
        '\u{ff13}' => output.push_str("3"),
        '\u{ff14}' => output.push_str("4"),
        '\u{ff15}' => output.push_str("5"),
        '\u{ff16}' => output.push_str("6"),
        '\u{ff17}' => output.push_str("7"),
        '\u{ff18}' => output.push_str("8"),
        '\u{ff19}' => output.push_str("9"),
        '\u{ff1a}' => output.push_str(":"),
        '\u{ff1b}' => output.push_str(";"),
        '\u{ff1c}' => output.push_str("<"),
        '\u{ff1d}' => output.push_str("="),
        '\u{ff1e}' => output.push_str(">"),
        '\u{ff1f}' => output.push_str("?"),
        '\u{ff20}' => output.push_str("@"),
        '\u{c0}' | '\u{c1}' | '\u{c2}' | '\u{c3}' | '\u{c4}' | '\u{c5}' | '\u{100}' | '\u{102}'
        | '\u{104}' | '\u{1cd}' | '\u{1de}' | '\u{1e0}' | '\u{1fa}' | '\u{200}' | '\u{202}'
        | '\u{226}' | '\u{1e00}' | '\u{1ea0}' | '\u{1ea2}' | '\u{1ea4}' | '\u{1ea6}'
        | '\u{1ea8}' | '\u{1eaa}' | '\u{1eac}' | '\u{1eae}' | '\u{1eb0}' | '\u{1eb2}'
        | '\u{1eb4}' | '\u{1eb6}' | '\u{ff21}' => output.push_str("A"),
        '\u{c6}' | '\u{1e2}' | '\u{1fc}' => output.push_str("AE"),
        '\u{1e02}' | '\u{1e04}' | '\u{1e06}' | '\u{ff22}' => output.push_str("B"),
        '\u{c7}' | '\u{106}' | '\u{108}' | '\u{10a}' | '\u{10c}' | '\u{1e08}' | '\u{ff23}' => {
            output.push_str("C")
        }
        '\u{10e}' | '\u{1e0a}' | '\u{1e0c}' | '\u{1e0e}' | '\u{1e10}' | '\u{1e12}' | '\u{ff24}' => {
            output.push_str("D")
        }
        '\u{1c4}' | '\u{1f1}' => output.push_str("DZ"),
        '\u{1c5}' | '\u{1f2}' => output.push_str("Dz"),
        '\u{c8}' | '\u{c9}' | '\u{ca}' | '\u{cb}' | '\u{112}' | '\u{114}' | '\u{116}'
        | '\u{118}' | '\u{11a}' | '\u{204}' | '\u{206}' | '\u{228}' | '\u{1e14}' | '\u{1e16}'
        | '\u{1e18}' | '\u{1e1a}' | '\u{1e1c}' | '\u{1eb8}' | '\u{1eba}' | '\u{1ebc}'
        | '\u{1ebe}' | '\u{1ec0}' | '\u{1ec2}' | '\u{1ec4}' | '\u{1ec6}' | '\u{ff25}' => {
            output.push_str("E")
        }
        '\u{1e1e}' | '\u{ff26}' => output.push_str("F"),
        '\u{11c}' | '\u{11e}' | '\u{120}' | '\u{122}' | '\u{1e6}' | '\u{1f4}' | '\u{1e20}'
        | '\u{ff27}' => output.push_str("G"),
        '\u{124}' | '\u{21e}' | '\u{1e22}' | '\u{1e24}' | '\u{1e26}' | '\u{1e28}' | '\u{1e2a}'
        | '\u{ff28}' => output.push_str("H"),
        '\u{cc}' | '\u{cd}' | '\u{ce}' | '\u{cf}' | '\u{128}' | '\u{12a}' | '\u{12c}'
        | '\u{12e}' | '\u{130}' | '\u{1cf}' | '\u{208}' | '\u{20a}' | '\u{1e2c}' | '\u{1e2e}'
        | '\u{1ec8}' | '\u{1eca}' | '\u{ff29}' => output.push_str("I"),
        '\u{132}' => output.push_str("IJ"),
        '\u{134}' | '\u{ff2a}' => output.push_str("J"),
        '\u{136}' | '\u{1e8}' | '\u{1e30}' | '\u{1e32}' | '\u{1e34}' | '\u{ff2b}' => {
            output.push_str("K")
        }
        '\u{139}' | '\u{13b}' | '\u{13d}' | '\u{1e36}' | '\u{1e38}' | '\u{1e3a}' | '\u{1e3c}'
        | '\u{ff2c}' => output.push_str("L"),
        '\u{1c7}' => output.push_str("LJ"),
        '\u{1c8}' => output.push_str("Lj"),
        '\u{13f}' => output.push_str("L·"),
        '\u{1e3e}' | '\u{1e40}' | '\u{1e42}' | '\u{ff2d}' => output.push_str("M"),
        '\u{d1}' | '\u{143}' | '\u{145}' | '\u{147}' | '\u{1f8}' | '\u{1e44}' | '\u{1e46}'
        | '\u{1e48}' | '\u{1e4a}' | '\u{ff2e}' => output.push_str("N"),
        '\u{1ca}' => output.push_str("NJ"),
        '\u{1cb}' => output.push_str("Nj"),
        '\u{d2}' | '\u{d3}' | '\u{d4}' | '\u{d5}' | '\u{d6}' | '\u{14c}' | '\u{14e}'
        | '\u{150}' | '\u{1a0}' | '\u{1d1}' | '\u{1ea}' | '\u{1ec}' | '\u{20c}' | '\u{20e}'
        | '\u{22a}' | '\u{22c}' | '\u{22e}' | '\u{230}' | '\u{1e4c}' | '\u{1e4e}' | '\u{1e50}'
        | '\u{1e52}' | '\u{1ecc}' | '\u{1ece}' | '\u{1ed0}' | '\u{1ed2}' | '\u{1ed4}'
        | '\u{1ed6}' | '\u{1ed8}' | '\u{1eda}' | '\u{1edc}' | '\u{1ede}' | '\u{1ee0}'
        | '\u{1ee2}' | '\u{ff2f}' => output.push_str("O"),
        '\u{152}' => output.push_str("OE"),
        '\u{1e54}' | '\u{1e56}' | '\u{ff30}' => output.push_str("P"),
        '\u{ff31}' => output.push_str("Q"),
        '\u{154}' | '\u{156}' | '\u{158}' | '\u{210}' | '\u{212}' | '\u{1e58}' | '\u{1e5a}'
        | '\u{1e5c}' | '\u{1e5e}' | '\u{ff32}' => output.push_str("R"),
        '\u{15a}' | '\u{15c}' | '\u{15e}' | '\u{160}' | '\u{218}' | '\u{1e60}' | '\u{1e62}'
        | '\u{1e64}' | '\u{1e66}' | '\u{1e68}' | '\u{ff33}' => output.push_str("S"),
        '\u{162}' | '\u{164}' | '\u{21a}' | '\u{1e6a}' | '\u{1e6c}' | '\u{1e6e}' | '\u{1e70}'
        | '\u{ff34}' => output.push_str("T"),
        '\u{d9}' | '\u{da}' | '\u{db}' | '\u{dc}' | '\u{168}' | '\u{16a}' | '\u{16c}'
        | '\u{16e}' | '\u{170}' | '\u{172}' | '\u{1af}' | '\u{1d3}' | '\u{1d5}' | '\u{1d7}'
        | '\u{1d9}' | '\u{1db}' | '\u{214}' | '\u{216}' | '\u{1e72}' | '\u{1e74}' | '\u{1e76}'
        | '\u{1e78}' | '\u{1e7a}' | '\u{1ee4}' | '\u{1ee6}' | '\u{1ee8}' | '\u{1eea}'
        | '\u{1eec}' | '\u{1eee}' | '\u{1ef0}' | '\u{ff35}' => output.push_str("U"),
        '\u{1e7c}' | '\u{1e7e}' | '\u{ff36}' => output.push_str("V"),
        '\u{174}' | '\u{1e80}' | '\u{1e82}' | '\u{1e84}' | '\u{1e86}' | '\u{1e88}' | '\u{ff37}' => {
            output.push_str("W")
        }
        '\u{1e8a}' | '\u{1e8c}' | '\u{ff38}' => output.push_str("X"),
        '\u{dd}' | '\u{176}' | '\u{178}' | '\u{232}' | '\u{1e8e}' | '\u{1ef2}' | '\u{1ef4}'
        | '\u{1ef6}' | '\u{1ef8}' | '\u{ff39}' => output.push_str("Y"),
        '\u{179}' | '\u{17b}' | '\u{17d}' | '\u{1e90}' | '\u{1e92}' | '\u{1e94}' | '\u{ff3a}' => {
            output.push_str("Z")
        }
        '\u{ff3b}' => output.push_str("["),
        '\u{ff3c}' => output.push_str("\\"),
        '\u{ff3d}' => output.push_str("]"),
        '\u{ff3e}' => output.push_str("^"),
        '\u{ff40}' => output.push_str("`"),
        '\u{e0}' | '\u{e1}' | '\u{e2}' | '\u{e3}' | '\u{e4}' | '\u{e5}' | '\u{101}' | '\u{103}'
        | '\u{105}' | '\u{1ce}' | '\u{1df}' | '\u{1e1}' | '\u{1fb}' | '\u{201}' | '\u{203}'
        | '\u{227}' | '\u{1e01}' | '\u{1ea1}' | '\u{1ea3}' | '\u{1ea5}' | '\u{1ea7}'
        | '\u{1ea9}' | '\u{1eab}' | '\u{1ead}' | '\u{1eaf}' | '\u{1eb1}' | '\u{1eb3}'
        | '\u{1eb5}' | '\u{1eb7}' | '\u{ff41}' => output.push_str("a"),
        '\u{e6}' | '\u{1e3}' | '\u{1fd}' => output.push_str("ae"),
        '\u{1e9a}' => output.push_str("aʾ"),
        '\u{1e03}' | '\u{1e05}' | '\u{1e07}' | '\u{ff42}' => output.push_str("b"),
        '\u{e7}' | '\u{107}' | '\u{109}' | '\u{10b}' | '\u{10d}' | '\u{1e09}' | '\u{ff43}' => {
            output.push_str("c")
        }
        '\u{d0}' | '\u{f0}' | '\u{10f}' | '\u{110}' | '\u{111}' | '\u{1e0b}' | '\u{1e0d}'
        | '\u{1e0f}' | '\u{1e11}' | '\u{1e13}' | '\u{ff44}' => output.push_str("d"),
        '\u{1c6}' | '\u{1f3}' => output.push_str("dz"),
        '\u{e8}' | '\u{e9}' | '\u{ea}' | '\u{eb}' | '\u{113}' | '\u{115}' | '\u{117}'
        | '\u{119}' | '\u{11b}' | '\u{18f}' | '\u{1dd}' | '\u{205}' | '\u{207}' | '\u{229}'
        | '\u{259}' | '\u{1e15}' | '\u{1e17}' | '\u{1e19}' | '\u{1e1b}' | '\u{1e1d}'
        | '\u{1eb9}' | '\u{1ebb}' | '\u{1ebd}' | '\u{1ebf}' | '\u{1ec1}' | '\u{1ec3}'
        | '\u{1ec5}' | '\u{1ec7}' | '\u{ff45}' => output.push_str("e"),
        '\u{1e1f}' | '\u{ff46}' => output.push_str("f"),
        '\u{11d}' | '\u{11f}' | '\u{121}' | '\u{123}' | '\u{1e7}' | '\u{1f5}' | '\u{1e21}'
        | '\u{ff47}' => output.push_str("g"),
        '\u{125}' | '\u{126}' | '\u{127}' | '\u{21f}' | '\u{1e23}' | '\u{1e25}' | '\u{1e27}'
        | '\u{1e29}' | '\u{1e2b}' | '\u{1e96}' | '\u{ff48}' => output.push_str("h"),
        '\u{ec}' | '\u{ed}' | '\u{ee}' | '\u{ef}' | '\u{129}' | '\u{12b}' | '\u{12d}'
        | '\u{12f}' | '\u{131}' | '\u{1d0}' | '\u{209}' | '\u{20b}' | '\u{1e2d}' | '\u{1e2f}'
        | '\u{1ec9}' | '\u{1ecb}' | '\u{ff49}' => output.push_str("i"),
        '\u{133}' => output.push_str("ij"),
        '\u{135}' | '\u{1f0}' | '\u{ff4a}' => output.push_str("j"),
        '\u{137}' | '\u{1e9}' | '\u{1e31}' | '\u{1e33}' | '\u{1e35}' | '\u{ff4b}' => {
            output.push_str("k")
        }
        '\u{13a}' | '\u{13c}' | '\u{13e}' | '\u{141}' | '\u{142}' | '\u{1e37}' | '\u{1e39}'
        | '\u{1e3b}' | '\u{1e3d}' | '\u{ff4c}' => output.push_str("l"),
        '\u{1c9}' => output.push_str("lj"),
        '\u{140}' => output.push_str("l·"),
        '\u{1e3f}' | '\u{1e41}' | '\u{1e43}' | '\u{ff4d}' => output.push_str("m"),
        '\u{f1}' | '\u{144}' | '\u{146}' | '\u{148}' | '\u{149}' | '\u{1f9}' | '\u{1e45}'
        | '\u{1e47}' | '\u{1e49}' | '\u{1e4b}' | '\u{ff4e}' => output.push_str("n"),
        '\u{1cc}' => output.push_str("nj"),
        '\u{d8}' | '\u{f2}' | '\u{f3}' | '\u{f4}' | '\u{f5}' | '\u{f6}' | '\u{f8}' | '\u{14d}'
        | '\u{14f}' | '\u{151}' | '\u{1a1}' | '\u{1d2}' | '\u{1eb}' | '\u{1ed}' | '\u{1fe}'
        | '\u{1ff}' | '\u{20d}' | '\u{20f}' | '\u{22b}' | '\u{22d}' | '\u{22f}' | '\u{231}'
        | '\u{1e4d}' | '\u{1e4f}' | '\u{1e51}' | '\u{1e53}' | '\u{1ecd}' | '\u{1ecf}'
        | '\u{1ed1}' | '\u{1ed3}' | '\u{1ed5}' | '\u{1ed7}' | '\u{1ed9}' | '\u{1edb}'
        | '\u{1edd}' | '\u{1edf}' | '\u{1ee1}' | '\u{1ee3}' | '\u{ff4f}' => output.push_str("o"),
        '\u{153}' => output.push_str("oe"),
        '\u{1e55}' | '\u{1e57}' | '\u{ff50}' => output.push_str("p"),
        '\u{ff51}' => output.push_str("q"),
        '\u{155}' | '\u{157}' | '\u{159}' | '\u{211}' | '\u{213}' | '\u{1e59}' | '\u{1e5b}'
        | '\u{1e5d}' | '\u{1e5f}' | '\u{ff52}' => output.push_str("r"),
        '\u{15b}' | '\u{15d}' | '\u{15f}' | '\u{161}' | '\u{17f}' | '\u{219}' | '\u{1e61}'
        | '\u{1e63}' | '\u{1e65}' | '\u{1e67}' | '\u{1e69}' | '\u{1e9b}' | '\u{ff53}' => {
            output.push_str("s")
        }
        '\u{df}' | '\u{1e9e}' => output.push_str("ss"),
        '\u{163}' | '\u{165}' | '\u{21b}' | '\u{1e6b}' | '\u{1e6d}' | '\u{1e6f}' | '\u{1e71}'
        | '\u{1e97}' | '\u{ff54}' => output.push_str("t"),
        '\u{de}' | '\u{fe}' => output.push_str("th"),
        '\u{f9}' | '\u{fa}' | '\u{fb}' | '\u{fc}' | '\u{169}' | '\u{16b}' | '\u{16d}'
        | '\u{16f}' | '\u{171}' | '\u{173}' | '\u{1b0}' | '\u{1d4}' | '\u{1d6}' | '\u{1d8}'
        | '\u{1da}' | '\u{1dc}' | '\u{215}' | '\u{217}' | '\u{1e73}' | '\u{1e75}' | '\u{1e77}'
        | '\u{1e79}' | '\u{1e7b}' | '\u{1ee5}' | '\u{1ee7}' | '\u{1ee9}' | '\u{1eeb}'
        | '\u{1eed}' | '\u{1eef}' | '\u{1ef1}' | '\u{ff55}' => output.push_str("u"),
        '\u{1e7d}' | '\u{1e7f}' | '\u{ff56}' => output.push_str("v"),
        '\u{175}' | '\u{1e81}' | '\u{1e83}' | '\u{1e85}' | '\u{1e87}' | '\u{1e89}' | '\u{1e98}'
        | '\u{ff57}' => output.push_str("w"),
        '\u{1e8b}' | '\u{1e8d}' | '\u{ff58}' => output.push_str("x"),
        '\u{fd}' | '\u{ff}' | '\u{177}' | '\u{233}' | '\u{1e8f}' | '\u{1e99}' | '\u{1ef3}'
        | '\u{1ef5}' | '\u{1ef7}' | '\u{1ef9}' | '\u{ff59}' => output.push_str("y"),
        '\u{17a}' | '\u{17c}' | '\u{17e}' | '\u{1e91}' | '\u{1e93}' | '\u{1e95}' | '\u{ff5a}' => {
            output.push_str("z")
        }
        '\u{ff5b}' => output.push_str("{"),
        '\u{ff5c}' => output.push_str("|"),
        '\u{ff5d}' => output.push_str("}"),
        '\u{ff5e}' => output.push_str("~"),
        '\u{1ee}' => output.push_str("Ʒ"),
        '\u{1ef}' => output.push_str("ʒ"),
        character => output.push(character),
    }
}

/// Normalize a country/state name using the same folding and `the` handling
/// as Euler StateISO.
fn normalize_state_name(value: &str) -> String {
    let mut folded = String::new();
    for character in value.chars() {
        if !is_combining_mark(character) {
            fold_character(character, &mut folded);
        }
    }
    let normalized = folded.to_lowercase();
    let normalized = normalized.split_whitespace().collect::<Vec<_>>().join(" ");
    let normalized = normalized.strip_prefix("the ").unwrap_or(&normalized);
    normalized
        .strip_suffix(" the")
        .unwrap_or(normalized)
        .to_owned()
}

/// Convert a state/province name to its ISO 3166-2 subdivision suffix.
///
/// Euler stores full values such as `US-CA` and `IN-KA`; this function
/// returns the suffix (`CA` or `KA`) required by connector fields.
pub fn convert_state_to_code(country: CountryAlpha2, state: &str) -> Option<&'static str> {
    let normalized_state = normalize_state_name(state);
    let country_code = country.to_string();
    STATE_CODE_MAP
        .get(&(country_code.as_str(), normalized_state.as_str()))
        .copied()
}
